  "Fabia":{"pl":"Z łacińskiego rodowego Fabius, prawdopodobnie od „faba” — bób.","en":"From the Latin gens name Fabius, probably from “faba” — bean.","d":[]},
  "Fabian":{"pl":"Z łacińskiego Fabianus, pochodne od rzymskiego rodu Fabiuszów, prawdopodobnie od „faba” — bób.","en":"From Latin Fabianus, derived from the Roman gens Fabius, probably from “faba” — bean.","d":["Fabianek"]},
  "Fabiana":{"pl":"Żeńska forma imienia Fabian, od łacińskiego rodu Fabiuszów.","en":"Female form of Fabian, from the Latin gens Fabius.","d":[]},
  "Fabiola":{"pl":"Zdrobniała łacińska forma imienia Fabia, od rodu Fabiuszów.","en":"A diminutive Latin form of Fabia, from the gens Fabius.","d":[]},
  "Fabiusz":{"pl":"Z łacińskiego rodowego Fabius, prawdopodobnie od „faba” — bób.","en":"From the Latin gens name Fabius, probably from “faba” — bean.","d":[]},
  "Fabrycjan":{"pl":"Z łacińskiego Fabricianus, od „faber” — rzemieślnik.","en":"From Latin Fabricianus, from “faber” — craftsman.","d":[]},
  "Faina":{"pl":"Z greckiego „phainein” — świecić, jaśnieć.","en":"From Greek “phainein” — to shine, to appear bright.","d":[]},
  "Falibog":{"pl":"Staropolskie: „fali-” (chwal) + „-bog” (bóg) — „chwal Boga”.","en":"Old Polish: “fali-” (praise) + “-bog” (god) — “praise God”.","d":[]},
  "Falibor":{"pl":"Staropolskie: „fali-” (chwal) + „-bor” (bój, walka) — „chwalebny w boju”.","en":"Old Polish: “fali-” (praise) + “-bor” (battle, fight) — “glorious in battle”.","d":[]},
  "Falimir":{"pl":"Staropolskie: „fali-” (chwal) + „-mir” (pokój) — „chwal pokój”.","en":"Old Polish: “fali-” (praise) + “-mir” (peace) — “praise peace”.","d":[]},
  "Falisław":{"pl":"Staropolskie: „fali-” (chwal) + „-sław” (sława) — „chwal sławę, godny chwały”.","en":"Old Polish: “fali-” (praise) + “-sław” (glory) — “praise glory, worthy of fame”.","d":[]},
  "Falkon":{"pl":"Prawdopodobnie od łacińskiego „falco” — sokół.","en":"Probably from Latin “falco” — falcon.","d":[]},
  "Faro":{"pl":"Pochodzenie niepewne; imię znane od wczesnośredniowiecznego świętego biskupa Meaux.","en":"Origin uncertain; known from an early medieval saint, a bishop of Meaux.","d":[]},
  "Faust":{"pl":"Z łacińskiego „faustus” — szczęśliwy, pomyślny.","en":"From Latin “faustus” — fortunate, auspicious.","d":[]},
  "Fausta":{"pl":"Żeńska forma od łacińskiego „faustus” — szczęśliwa, pomyślna.","en":"Female form from Latin “faustus” — fortunate, auspicious.","d":[]},
  "Faustyn":{"pl":"Z łacińskiego Faustinus, zdrobnienie od „faustus” — szczęśliwy.","en":"From Latin Faustinus, a diminutive of “faustus” — fortunate.","d":[]},
  "Faustyna":{"pl":"Żeńska forma od łacińskiego Faustinus — „szczęśliwa”. Znana m.in. dzięki św. Faustynie Kowalskiej.","en":"Female form of Faustinus — “fortunate”. Known especially through St. Faustyna Kowalska.","d":["Faustynka"]},
  "Faustynian":{"pl":"Z łacińskiego Faustinianus, od „faustus” — szczęśliwy.","en":"From Latin Faustinianus, from “faustus” — fortunate.","d":[]},
  "Fawila":{"pl":"Pochodzenie niepewne, prawdopodobnie z wizygockiego imienia Favila.","en":"Origin uncertain, probably from the Visigothic name Favila.","d":[]},
