  "Feliksa":{"pl":"Żeńska forma imienia Feliks, od łacińskiego „felix” — szczęśliwa.","en":"Female form of Feliks, from Latin “felix” — happy, fortunate.","d":["Felcia"]},
  "Felin":{"pl":"Pochodzenie niepewne, być może zdrobnienie imienia Feliks.","en":"Origin uncertain, possibly a short form related to Feliks.","d":[]},
  "Felina":{"pl":"Pochodzenie niepewne, być może żeńska forma powiązana z imieniem Felin lub Feliks.","en":"Origin uncertain, possibly a female form related to Felin or Feliks.","d":[]},
  "Fenenna":{"pl":"Z hebrajskiego biblijnego imienia Peninna — „perła” lub „koral”.","en":"From the Hebrew biblical name Peninnah — “pearl” or “coral”.","d":[]},
  "Ferdynand":{"pl":"Germańskie, prawdopodobnie od „fardi” (podróż) i „nand” (odważny) — „odważny w drodze”.","en":"Germanic, probably from “fardi” (journey) and “nand” (bold) — “bold on the journey”.","d":["Ferdek"]},
  "Fereol":{"pl":"Z łacińskiego Fereolus, pochodzenie niepewne; imię znane od wczesnego świętego francuskiego.","en":"From Latin Fereolus, origin uncertain; known from an early French saint.","d":[]},
  "Festus":{"pl":"Z łacińskiego „festus” — świąteczny, radosny.","en":"From Latin “festus” — festive, joyful.","d":[]},
