  "Fidelisa":{"pl":"Żeńska forma od łacińskiego „fidelis” — wierna.","en":"Female form from Latin “fidelis” — faithful.","d":[]},
  "Fidol":{"pl":"Pochodzenie niepewne, prawdopodobnie powiązane z łacińskim „fidelis” — wierny.","en":"Origin uncertain, possibly related to Latin “fidelis” — faithful.","d":[]},
  "Fiebrosław":{"pl":"Pochodzenie niepewne; drugi człon to staropolskie „-sław” (sława).","en":"Origin uncertain; the second element is Old Polish “-sław” (glory, fame).","d":[]},
  "Filadelf":{"pl":"Z greckiego philos + adelphos — „miłujący brata”.","en":"From Greek philos + adelphos — “brother-loving”.","d":[]},
  "Filadelfia":{"pl":"Z greckiego philos + adelphos — „miłość braterska”.","en":"From Greek philos + adelphos — “brotherly love”.","d":[]},
  "Filaret":{"pl":"Z greckiego philos + arete — „miłujący cnotę”.","en":"From Greek philos + arete — “lover of virtue”.","d":[]},
  "Filemon":{"pl":"Z greckiego „philein” — kochać; „przyjazny, kochający”.","en":"From Greek “philein” — to love; “friendly, loving”.","d":[]},
  "Filemona":{"pl":"Żeńska forma imienia Filemon, od greckiego „philein” — kochać.","en":"Female form of Filemon, from Greek “philein” — to love.","d":[]},
  "Filibert":{"pl":"Germańskie, od „fili” (bardzo) i „beraht” (jasny, sławny) — „bardzo sławny”.","en":"Germanic, from “fili” (very) and “beraht” (bright, famous) — “very famous”.","d":[]},
  "Filiberta":{"pl":"Żeńska forma imienia Filibert — „bardzo sławna”.","en":"Female form of Filibert — “very famous”.","d":[]},
  "Filip":{"pl":"Z greckiego philos + hippos — „miłujący konie”.","en":"From Greek philos + hippos — “horse-lover”.","d":["Filipek"]},
  "Filip Neriusz":{"pl":"Złożenie imienia Filip z przydomkiem Neri (św. Filip Neri), o niepewnym pochodzeniu przydomka.","en":"A compound of Filip with the byname Neri (from St. Philip Neri), the byname's origin uncertain.","d":[]},
  "Filipa":{"pl":"Żeńska forma imienia Filip, z greckiego philos + hippos — „miłująca konie”.","en":"Female form of Filip, from Greek philos + hippos — “horse-lover”.","d":["Filipka"]},
  "Filipina":{"pl":"Pochodna żeńska imienia Filip, z greckiego philos + hippos — „miłująca konie”.","en":"A female derivative of Filip, from Greek philos + hippos — “horse-lover”.","d":[]},
  "Filomen":{"pl":"Pochodzenie niepewne, powiązane z greckim philos — „kochający”; etymologia dokładnego drugiego członu sporna.","en":"Origin uncertain, related to Greek philos — “loving”; the exact second element is disputed.","d":[]},
  "Filomena":{"pl":"Pochodzenie niepewne, powiązane z greckim philos — „kochająca”; etymologia dokładnego drugiego członu sporna.","en":"Origin uncertain, related to Greek philos — “loving”; the exact second element is disputed.","d":[]},
  "Filon":{"pl":"Z greckiego „philon” — kochający, przyjazny.","en":"From Greek “philon” — loving, friendly.","d":[]},
