  "Fintan":{"pl":"Imię irlandzkie (gaelickie), pochodzenie niepewne; znane od wczesnych świętych irlandzkich.","en":"An Irish (Gaelic) name of uncertain origin, known from early Irish saints.","d":[]},
  "Firmin":{"pl":"Z łacińskiego „firmus” — mocny, stanowczy.","en":"From Latin “firmus” — firm, steadfast.","d":[]},
